python3 << 'EOF'
import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-reading-list/ReadingListBpmn/ReadingListBpmn.bpmn')
root = tree.getroot()

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'dc': 'http://www.omg.org/spec/DD/20100524/DC',
    'di': 'http://www.omg.org/spec/DD/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

errors = []

# 1. Root has definitions with required namespaces
tag = root.tag
if 'definitions' not in tag:
    errors.append(f"Root is not definitions: {tag}")

# Collect all declared ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}
print(f"All IDs: {all_ids}")

# Collect all sequence flow ids
flows = root.findall('.//bpmn:sequenceFlow', NS)
flow_ids = {f.get('id') for f in flows}
print(f"Flows: {flow_ids}")

# Check all sourceRef/targetRef resolve
for f in flows:
    src = f.get('sourceRef')
    tgt = f.get('targetRef')
    if src not in all_ids:
        errors.append(f"Flow {f.get('id')} sourceRef '{src}' not found")
    if tgt not in all_ids:
        errors.append(f"Flow {f.get('id')} targetRef '{tgt}' not found")

# 2. BPMNDiagram exists
diagrams = root.findall('.//bpmndi:BPMNDiagram', NS)
if not diagrams:
    errors.append("No BPMNDiagram found")
else:
    # Check shapes and edges
    shapes = root.findall('.//bpmndi:BPMNShape', NS)
    edges = root.findall('.//bpmndi:BPMNEdge', NS)
    shape_refs = {s.get('bpmnElement') for s in shapes}
    edge_refs = {e.get('bpmnElement') for e in edges}
    print(f"Shape refs: {shape_refs}")
    print(f"Edge refs: {edge_refs}")

    # Every flow node needs a shape
    flow_nodes = []
    for tag_name in ['startEvent', 'endEvent', 'scriptTask', 'task', 'serviceTask', 'userTask', 'exclusiveGateway', 'parallelGateway']:
        flow_nodes.extend(root.findall(f'.//bpmn:{tag_name}', NS))
    for node in flow_nodes:
        nid = node.get('id')
        if nid not in shape_refs:
            errors.append(f"Node '{nid}' has no BPMNShape")

    # Every flow needs an edge
    for fid in flow_ids:
        if fid not in edge_refs:
            errors.append(f"Flow '{fid}' has no BPMNEdge")

# 3. No XOR gateways with missing conditions (none here)
gws = root.findall('.//bpmn:exclusiveGateway', NS)
for gw in gws:
    outgoing = gw.findall('bpmn:outgoing', NS)
    default = gw.get('default')
    if len(outgoing) > 1:
        if not default:
            errors.append(f"XOR gateway '{gw.get('id')}' has no default")

# 4. No activity/event with more than one incoming flow
for el in root.iter():
    incoming = list(el.findall('bpmn:incoming', NS))
    if len(incoming) > 1:
        errors.append(f"Element '{el.get('id')}' has multiple incoming flows (fake join)")

# 5. Variables referenced in expressions resolve
declared_var_ids = set()
for var in root.findall('.//uipath:inputOutput', NS):
    declared_var_ids.add(var.get('id'))
print(f"Declared variable IDs: {declared_var_ids}")

# Check uipath:output var= attributes
for out in root.findall('.//uipath:output', NS):
    var_ref = out.get('var')
    if var_ref and var_ref not in declared_var_ids:
        errors.append(f"Output mapping var='{var_ref}' not declared")

# Check script version v3 on all script tasks
for st in root.findall('.//bpmn:scriptTask', NS):
    sv = st.find('.//uipath:scriptVersion', NS)
    if sv is None:
        errors.append(f"ScriptTask '{st.get('id')}' missing uipath:scriptVersion")
    elif sv.get('value') != 'v3':
        errors.append(f"ScriptTask '{st.get('id')}' has scriptVersion {sv.get('value')} (expected v3)")

if errors:
    for e in errors:
        print(f"ERROR: {e}")
else:
    print("VALID - all structural checks passed")
EOF

